style.css:
@-moz-document url-prefix("https://baselinker.com") {
.product-name.name-container.pointer {
    border: 1px solid #cdcdcd;
    z-index: 100;
    font-size: 14px;
    padding: 5px;
    letter-spacing: .1rem;
    width: 800px;
    border-radius: 3px;
    font-weight: normal;
    background: url(https://i.imgur.com/RdmyuBk.jpeg) no-repeat;
    background-position: right center;
    background-size: 96px 40px;
    overflow: hidden;
    font-family: monospace;
    color: #042c54;
  	zoom: 1.05;
  }

.table_inventory_products tr:nth-child(even) {
  background: #f7f7f7;
	}
}
